/**
 * The English dictionary — the source of truth for the key set (`TranslationKey`
 * in `./index`). A pure data module with no imports: `index.ts` fills `{app}`
 * and builds the loader, store and `useT` around it.
 */

// English is the base: it defines the full key set. Other languages need only
// override; anything absent falls through to English via `translate`. The app's
// name is written `{app}` in every dictionary and filled from `BRAND.display`
// where the dictionary is loaded (`en` in `./index`, `registerDict` for the others).
// Exported solely for the tests — components go through `useT()`/`translate`.
