  "theme.group.surfaces": "Surfaces",
  "theme.group.surfaces.help": "The window, its panels, and the chrome headers above them — the subwindow tab bars and file-panel headers that share one secondary surface. The app's own top bar follows --bg-header from here until you give it a fill of its own in Top frame, below.",
  "theme.group.topframe": "Top frame",
  "theme.group.topframe.help": "{app}'s own title bar — the strip carrying the clock, the project pills and the window buttons. Three layers make it: a fill, an accent wash over that fill, and the seam under it that says where the app's chrome stops and its content begins. Each follows a shared token until you set it, so the bar can be retoned without the accent moving through the rest of the window with it. The three text tiers below are remapped for the bar's whole subtree, so one value moves every label on it at once — the menus that drop out of the bar keep the theme's own ink.",
  "theme.group.subwindow": "Subwindows",
  "theme.group.subwindow.help": "A subwindow's own header — the tab bar over each pane — plus the two markers that say which subwindow has the focus. The bar shares the app's secondary-chrome surface with every file-panel header row, and its markers read the bare accent, so none of it could be moved on its own before. Set a text tier here and the whole bar follows: tab labels, the grip, the chevrons, the chips.",
  "theme.group.sidepanel": "Side panel",
  "theme.group.sidepanel.help": "The file panel that slides in from the edge, on its own. Each value here follows the shared token it would otherwise read, so the panel only parts company with the rest of the window once you set one — and the header rows move without taking the subwindow tab bars with them.",
  "theme.group.alerts": "Alerts strip",
  "theme.group.alerts.help": "The alerts group under the file tree — urgent mail, the next appointments, the cards due. Its look is derived from the accent, the window ground and the status hues; these values are that derivation, so the strip can be retoned without moving what it borrows from.",
  "theme.group.text": "Text",
  "theme.group.text.help": "The three text tiers, brightest to dimmest.",
  "theme.group.borders": "Borders",
  "theme.group.borders.help": "Separators and outlines — the visible one, and the whisper.",
  "theme.group.accent": "Accent",
  "theme.group.accent.help": "The theme's own hue and its states. The accent itself is one cross-theme setting of its own — pick a preset or any other color, and the rest derive from it until set here.",
  "theme.group.controls": "Controls",
  "theme.group.controls.help": "Inputs and buttons, plus the neutral hover and inset washes that sit over any surface.",
  "theme.group.status": "Status",
  "theme.group.status.help": "Success, warning and danger, and the task-state hues beside them.",
