  "mobile.guideSummary": "Set up Tailscale Serve",
  "mobile.windowsTerminalsNote": "On Windows the phone cannot open this computer's terminals or agent tabs: they attach through tmux, which Windows does not have.",
  "mobile.guideIntro": "Before turning on {app} Mobile, install Tailscale and sign in here, then sign in to the same tailnet on your phone or tablet.",
  "mobile.guideStep1a": "In a terminal on this computer, inspect its existing publication with",
  "mobile.guideStep1b": ". {app} Mobile needs the HTTPS / (root) handler, so do not replace an existing root handler unless you mean to move that service.",
  "mobile.guideStep2a": "Configure the private, persistent reverse proxy. Use Serve—not Funnel:",
  "mobile.guideStep2b": "If Tailscale asks for approval or HTTPS setup, complete it in the browser it opens.",
  "mobile.guideStep3a": "Run",
  "mobile.guideStep3b": "again, then use",
  "mobile.guideStep3c": "below. {app} fills the computer name, loopback port, and verified origin from the private root mapping.",
  "mobile.guideStep4a": "Turn on {app} Mobile. {app} verifies that the origin's root handler proxies exactly to",
  "mobile.guideStep4b": "; use",
  "mobile.guideStep4c": "if you changed Tailscale in another terminal.",
  "mobile.guideStep5": "Enable the projects you want to expose, create a pairing code, then open the verified origin on the phone or tablet and enter that code.",
  "mobile.guideOutro": "Only devices in your tailnet can reach the address, and each still needs pairing. Don't use Tailscale Funnel: it makes the service public and {app} will refuse to start.",
