  // Tabtivity Mobile — the setup instruction behind the header's phone icon while
  // Mobile is off (mobile/MobileSetupGuide). Same ground as the fold in Mobile
  // settings, written as the six things you do, in order.
  "mobile.setupTitle": "Set up {app} Mobile",
  "mobile.setupIntro": "{app} Mobile puts this computer's projects, terminals and agents on your phone. It travels over your own private Tailscale network: nothing is published to the internet, and the phone still has to be paired.",
  "mobile.setupStep1Title": "Install Tailscale on this computer",
  "mobile.setupStep1Body": "Install Tailscale here and sign in. It is what carries the phone's connection — {app} itself only ever listens on loopback.",
  "mobile.setupStep2Title": "Install Tailscale on the phone",
  "mobile.setupStep2Body": "Install the Tailscale app on the phone or tablet and sign in to the same tailnet as this computer.",
  "mobile.setupStep3Title": "Publish {app} privately",
  "mobile.setupStep3Body": "Point Tailscale Serve at {app}'s loopback port. Use Serve, never Funnel: Funnel would make it public and {app} refuses to start. If Tailscale asks for approval or HTTPS setup, complete it in the browser it opens.",
  "mobile.setupStep4Title": "Turn {app} Mobile on",
  "mobile.setupStep4Body": "In Settings → Mobile press “Detect Tailscale Serve settings”, check the computer name, port and origin it fills in, then switch {app} Mobile on. {app} verifies the mapping before it starts the host.",
  "mobile.setupStep5Title": "Choose what the phone may open",
  "mobile.setupStep5Body": "Under “Project access” in the same settings, enable the projects and boxes the phone may open. Everything is off until you enable it.",
  "mobile.setupStep6Title": "Pair the phone",
  "mobile.setupStep6Body": "Press “Show install QR” and scan it with the phone, then create a pairing code and enter it there. A code is valid for five minutes.",
  "mobile.setupOpenSettings": "Open Mobile settings",

  // Settings — usage stats.
  "settings.usageStats": "Usage stats",
  "settings.pdfMarkup": "PDF markup",
  "settings.pdfMarkupHelp": "What the PDF viewer’s Mark up sends to the agent. Kept on this computer; the phone has its own (Home → This device → Mark up prompt).",
  "settings.pdfMarkupInstruction": "Mark up prompt",
  "settings.pdfMarkupInstructionHelp": "Sent to the agent with each Submit, after the file, the marked copy and your notes. By default it has the agent make the changes and rebuild the PDF — or, with Apply marks directly off, list them first.",
  "settings.pdfMarkupApply": "“Make these changes” prompt",
  "settings.pdfMarkupApplyHelp": "Sent by the Make these changes button once the agent has listed what your marks ask for.",
  "settings.pdfMarkupAutoReload": "Reload the PDF under your marks when it changes",
  "settings.pdfMarkupAutoReloadHelp": "When the agent rebuilds the PDF you are marking, the new pages load under your marks. Off: the markup strip offers Reload PDF.",
  "settings.pdfMarkupSubagents": "Hand each Submit to a new subagent",
  "settings.pdfMarkupSubagentsHelp": "Each Submit hands the round to a new subagent, so the next round can go out without waiting. For agents that support subagents (Claude Code); others do the round themselves.",
  "settings.pdfMarkupDirect": "Apply marks directly",
  "settings.pdfMarkupDirectHelp": "Submit has the agent make the changes right away; Undo then restores every file the round changed. Off, or where no undo is possible (e.g. not a git repository), the agent lists the changes first.",
  "settings.pdfMarkupReset": "Use the default",
  "markup.ask.label": "Questions about your marks",
  "markup.ask.help": "How often the agent stops to ask you about a mark before it lists the changes. Put after the Mark up prompt with each Submit.",
  "markup.ask.stop0": "Ask always",
  "markup.ask.stop1": "Ask often",
  "markup.ask.stop2": "Ask when unsure",
  "markup.ask.stop3": "Ask rarely",
  "markup.ask.stop4": "Never ask",
  "markup.ask.hint0": "A question for every mark before it counts as a change.",
  "markup.ask.hint1": "Asks whenever a mark leaves any choice.",
  "markup.ask.hint2": "Asks only about marks it cannot read or real choices; takes the obvious reading for the rest.",
  "markup.ask.hint3": "Asks only when it cannot act on a mark at all without you.",
  "markup.ask.hint4": "Decides every unclear mark itself and lists what it decided.",
  "settings.dailyRecap": "Show the recap at the start of each day",
  "settings.openUsageStats": "Open usage stats",

