  "settings.energyUnavailable": "Power state unavailable — treating as AC (inactive).",
  "settings.energyActiveAlways": "Currently active — always on.",
  "settings.energyActiveBattery": "Currently active — running on battery.",
  "settings.energyOff": "Off — never throttles.",
  "settings.energyInactive": "Inactive — on AC power.",
  "settings.claudeRemoteHelp1": "Spawns Claude agent tabs with",
  "settings.claudeRemoteHelp2": "so you can monitor and steer them from the Claude app or web. Requires a Claude subscription login (not an API key); only Claude supports it.",
  "settings.agentFenceSharedState": "Each project, box and the root console has its own agent home inside {app}, never in your home folder. Logins are shared (below); your own instructions, skills and MCP entries are not brought in — add them per project.",
  "settings.agentGlobal": "Global agent config",
  "settings.agentGlobalHelp": "Instructions, skills, commands, hooks and MCP servers every {app} agent gets — your CLAUDE.md, AGENTS.md, settings.json hooks and the like. Import copies them from ~/.claude, ~/.codex, ~/.gemini and other CLIs (never logins or history). Each new agent tab gets a fresh copy; agents cannot change it.",
  "settings.agentGlobalFiles": "{count} files",
  "settings.agentGlobalEmpty": "Empty",
  "settings.agentGlobalImport": "Import from this computer",
  "settings.agentGlobalOpen": "Open folder",
  "settings.agentGlobalImported": "Imported {files} files and {configs} config files. New agent tabs pick them up.",
  "settings.codexAutoReview": "Codex: auto-review approvals",
  "settings.codexAutoReviewHelp": "Codex hands requests it would ask you about (commands outside its sandbox, network access, edits outside the project) to a reviewer agent that approves or refuses them. Without it, every command asks inside {app}'s sandbox on Linux. Each review is an extra model call.",
  "settings.agentLogins": "Agent logins",
  "settings.agentLoginsHelp": "One login per CLI, shared by every {app} agent: sign in once in any tab. Import copies this computer's existing login (never config). CLIs that keep their login elsewhere (Mistral Vibe, Aider, mini-swe-agent, Cline) are not listed and sign in per project.",
  "settings.agentLoginSignedIn": "signed in",
  "settings.agentLoginSignedInAs": "signed in as {account}",
  "settings.agentLoginNotSignedIn": "not signed in — log in once in any tab, or import",
  "settings.agentLoginImport": "Import from this computer",
  "settings.agentLoginSignOut": "Sign out",
  "settings.agentLoginBlocked": "A tab signed in as {account} while {app} holds {stored}: not adopted. Sign out first to switch accounts.",
  "settings.agentLoginBlockedCommand": "A tab wrote a login whose {field} is a command, not a key: not shared. Log in again with a plain key.",
  "settings.agentLoginBlockedConfig": "A tab's login brought more than a token refresh ({field}): only the refresh was shared. {app} shares an OpenCode login only as the sign-in you imported; add a provider by importing it again.",
  "settings.agentLoginWellknown": "OpenCode in {scope} loaded a remote configuration source ({origins}) and fetches that origin's settings (servers, plugins) at every start. Signing out here moves this scope's OpenCode database aside (its sessions list starts empty); close that scope's OpenCode tabs first.",
  "settings.agentLoginWellknownHost": "the Host session",
  "settings.agentLoginWellknownSignOut": "Sign out here",
  "settings.agentLoginAdminKey": "runs on the administrator's API key",
  "settings.agentLoginAdminKeyGone": "set to the administrator's API key, which is no longer offered to you (withdrawn, or you were taken off its list) — switch back to your own login",
  "settings.agentLoginAdminKeyHelp": "Run this CLI's agents on the administrator's API key instead of your login. The key never enters an agent, and your login stays saved for when you switch back. Choosing this turns off your own API key for this CLI.",
  "settings.agentApiKeys": "API keys",
  "settings.agentApiKeysCodexHelp": "Codex uses your OpenAI API key in new local tabs, including resumed conversations. Your saved ChatGPT login stays available when you switch back to its own login. API usage is billed separately from your ChatGPT subscription.",
  "settings.agentApiKeysHelp": "Pay per token instead of a subscription: save a provider's API key, then open a tab on it from the ＋ menu's API section — the menu's plain rows stay on the CLI's own login. The \"runs on\" choice below sets what tabs opened elsewhere use (the phone, scheduled agents). The key stays in the OS keyring; new local tabs reach the provider through {app} with a token of their own.",
  "settings.agentApiKeysWarning": "Agents never see the key, only a per-tab token that works through {app}. Still use a spend-limited key: an open tab can spend through its token.",
  "settings.agentApiKeysDialogs": "Claude uses the key at once (without Remote Control); Gemini only after you pick \"Use Gemini API key\" in its /auth. Switching a CLI reaches new tabs only; removing a key stops running tabs too. If a tab reports an invalid key, fix or remove it here — signing in again won't help.",
  "settings.agentApiKeySaved": "saved",
  "settings.agentApiKeyNotSaved": "not saved",
  "settings.agentApiKeyLocked": "keyring locked — unlock it to see or change this key",
  "settings.agentApiKeyVaultLocked": "locked — sign in on a paired device to unlock the key, then see or change this one here",
  "settings.agentApiKeyUnlock": "Unlock keyring",
  "settings.agentApiKeyPlaceholder": "Paste the {provider} API key",
  "settings.agentApiKeySave": "Save",
  "settings.agentApiKeyRemove": "Remove",
  "settings.agentApiWorkspace": "workspace {id}",
  "settings.agentApiWorkspacePick": "This key isn't tied to one workspace, so every request has to name one. Pick the workspace its usage runs in:",
  "settings.agentApiWorkspaceType": "This key isn't tied to one workspace, so every request has to name one, and it can't list them. Paste the workspace ID (wrkspc_…) from the Anthropic Console's Workspaces page:",
  "settings.agentApiWorkspaceLabel": "Anthropic workspace",
  "settings.agentApiWorkspaceCancel": "Cancel",
  "settings.agentCredRunsOn": "{cli} runs on",
  "settings.agentCredLogin": "its own login",
  "settings.agentCredOwnKey": "my API key ({providers})",
  "settings.agentCredAdminKey": "the administrator's API key",
  "settings.agentLoginUsesApiKey": "uses API key",
  "settings.agentLoginApiBudgetReached": "API budget reached",
  "settings.agentApiLimitHelp": "A monthly limit in billed tokens (cache reads count a tenth). {app} refuses new requests once it is reached; the count resets on {date} (UTC). The dollar figure is an estimate from prices dated {priced} — also set a spending limit with the provider.",
  "settings.agentApiLimitLabel": "Monthly limit for {provider}, million billed tokens",
  "settings.agentApiLimitSet": "Set limit",
  "settings.agentApiSpent": "{spent} of {limit} billed tokens this month, {left} left (≈ {usd})",
  "settings.agentApiModelUsage": "{model}: {input} in · {output} out",
