  "settings.agentApiModelCacheWrite": "{tokens} cache write",
  "settings.agentApiBudgetReached": "budget reached ({spent} of {limit} billed tokens) — new requests are refused until {date} or a higher limit",
  "settings.agentApiNoLimit": "no monthly limit — requests are refused until you set one",
  "settings.agentApiOldUsdLimit": "Limits are now in billed tokens; your earlier limit was {usd} a month. Set a token limit to use this key again.",
  "settings.agentApiUnknownModels": "Not in the price table, so their dollar estimate uses the highest {provider} rate: {models}",
  "settings.agentApiLedgerRestarted": "The usage record could not be read (kept aside); this month's count restarted at {date}.",
  "settings.agentFenceCargoCredentials": "Allow Cargo registry credential files",
  "settings.agentFenceCargoCredentialsHelp": "Off by default. Lets newly started agents read Cargo registry tokens, e.g. to publish a Rust package.",
  "settings.copilotFenceAuth": "Copilot sign-in for sandboxed tabs",
  "settings.copilotFenceAuthSignedIn": "Signed in as {login}.",
  "settings.copilotFenceAuthSignedInOffline": "Signed in. GitHub could not be reached to show the account.",
  "settings.copilotFenceAuthExpired": "The saved sign-in no longer works. Sign out, then run /login in a sandboxed Copilot tab.",
  "settings.copilotFenceAuthNone": "Not signed in. Run /login once in any sandboxed Copilot tab; every sandboxed Copilot tab started after that is signed in.",
  "settings.copilotFenceAuthHelp": "The sandbox hides the system keyring, so {app} keeps Copilot's sign-in in its own keyring entry and passes it to sandboxed tabs. To switch accounts, sign out first.",
  "settings.copilotFenceAuthSignOut": "Sign out",
  "settings.rootFenceProjects": "Root agent reads projects",
  "settings.rootFenceProjectsHelp": "Off by default. Lets sandboxed root-console agents read every project, box and remote mirror — e.g. to attach a file to a mail draft. Text in one project can then steer the agent into reading the others. Applies to new root tabs.",
  "settings.agentFenceTitle": "Agent sandbox",
  "settings.agentFenceEnabled": "Sandbox local agents to their project or box",
  "settings.agentFenceHelp": "Local agent tabs — including CLIs typed into a shell tab — always run sandboxed on Linux and macOS and can write only their project or box. To repair this computer, use the root console's Host session, which runs with your full rights.",
  "settings.agentFenceLimits": "Protects files only: network access and environment variables are shared, and readable files outside the agent home may stay visible. Remote and Windows agents run without the sandbox; containers use their own boundary. On macOS the keychain stays reachable; on Linux an agent's own sandbox may not work inside it.",
  "settings.agentFencePlatformAccepted": "Agents on this computer run with your full rights — accepted",
  "settings.agentFencePlatformAcceptedHelp": "Windows has no agent sandbox; you accepted that agents can read and change everything your account can. Switch this off to be asked again.",
  "settings.agentFencePaths": "Read-only toolchain/config paths (one per line)",
  "settings.agentFenceReset": "Reset to defaults",
  "settings.agentFencePathsHelp": "Paths from your home shown read-only to every sandboxed agent. Add a credential path only when an agent needs it (e.g. ~/.ssh for SSH pushes).",
  "settings.headlessRemoteHelp": "On (default): {app} connects SSH/OpenVPN in the background, holding the password only briefly. Off: each connection opens as a terminal in the root console and you type the password there yourself.",
  "settings.persistLocalHelp1": "When on (default), local shell and Python/script tabs run inside a tmux session, so long runs survive an {app} crash and reattach on restart. Requires",
  "settings.persistLocalHelp2": "; agent tabs are unaffected.",
  "settings.remoteFeaturesHelp": "Each adds a machine-wide header control: an OpenVPN tunnel (routes all traffic while up) and a list of SSH machines outside projects. Off by default.",
  "settings.energyHelp": "Saves power by pausing idle animations and slowing background refreshes. \"On battery\" (default) applies only while unplugged.",
  "settings.fastModeHelp": "Turns off extras that cost work: folder sizes, git dots on project pills, hover cards, the CPU/RAM readout, the Python Run check and animations. Nothing is lost. Helps on a slow disk, a busy machine or a thin link.",
  "settings.sleepTabsHelp": "Unloads tabs you have not looked at for this long to free memory; they reload where you left off, and terminals and agents keep running. Tabs with unsaved work, a running build or playing media stay loaded.",
  "settings.experimentalHelp1": "Features still in progress; each stays off until you tick it here.",
  "settings.experimentalHelp2": "Experiments Debug mode used to turn on stay ticked until you untick them.",
  "settings.experimentalHelp3": "Turning off a feature that owns tabs (Browser) also closes those tabs.",
  "settings.pythonRunHelp1": "Gives a",
  "settings.pythonRunHelp2": "file open in the editor a",
  "settings.pythonRunHelp3": "and a",
  "settings.pythonRunHelp4": "button and a breakpoint gutter. Both run in a terminal tab with the project's own interpreter — on the remote host or in the container where there is one. Debug is",
  "settings.pythonRunHelp5": " with your breakpoints. Off by default because Run executes the file; {modifier}+Click go-to-definition always works.",
  "settings.resourceMonitorHelp": "CPU and RAM of {app}'s own processes; GPU is the VRAM used by loaded Ollama models. Shown in the header next to the timer.",
  "settings.reminderHelp": "Reminders show as a desktop notification and a popup you can snooze. \"Day grid starts at\" only sets where the day and week views scroll to.",
  "settings.zoomHelp1": "Scales the whole {app} interface — handy on high-DPI screens. Zoom is",
  "settings.zoomHelpBold": "per window",
  "settings.zoomHelp2": ": popped-out windows keep their own. Ctrl + / Ctrl − zoom the focused window, Ctrl 0 resets.",
  "settings.minSubwindowHelp": "Smallest a subwindow may be made by dragging a split divider. Defaults to {px}px when left blank.",
