  "intro.projects.step3Body": "The + on a project's tab bar opens a shell, a file viewer or an AI agent in the project folder. Drag a tab to a pane edge to split the view.",
  "intro.agents.lead": "An agent tab runs an AI coding CLI in the project folder. {app} does not bundle them: install the ones you use, once per machine. The three most used are below; Settings → Manage CLIs has about thirty more.",
