  "server.calendarSharing.header": "Shared calendars and to-do lists",
  "server.calendarSharing.help": "Open one of your calendars to other users of this server: its events, its to-do list, or both, each as viewer or editor. Sharing a calendar moves it into the server's calendar service; stopping moves it back. A task's mail and file links, the appointment it came from and its project never leave your account, and reminders stay each person's own. Revoking stops their next read; copies they already made stay. The default calendar, CalDAV calendars and subscriptions cannot be shared.",
