  "server.secrets.header": "Secrets key",
  "server.secrets.help": "On this server your mail store and the passwords you chose to save are sealed under one key that only your paired devices (or your recovery code) can unlock. It is never written to disk in the clear: after a server reboot it stays locked until one of your devices signs in.",
  "server.secrets.connectNote": "In the desktop app's Connect window the secrets key cannot be set up, given a new recovery code or unlocked after a server reboot yet. Do that from the phone app or a browser signed in to this server; mail and saved passwords stay locked after a reboot until one of those signs in.",
  "server.secrets.notSetUp": "Not set up yet — mail on this server waits until it is.",
  "server.secrets.setUp": "Set up the key",
  "server.secrets.codeIntro": "Your recovery code. Write it down now: it is shown only this once and stored nowhere.",
  "server.secrets.codeLoss": "If every paired device and this code are lost, the saved passwords and local-only mail data (drafts, filters) are lost too; mail itself is fetched again from the server.",
  "server.secrets.codeSaved": "I have written it down",
  "server.secrets.unlocked": "Unlocked: mail and saved passwords are open.",
  "server.secrets.newCode": "New recovery code",
  "server.secrets.locked": "Locked since the server restarted. Sign in on a paired phone or browser to unlock it, or enter your recovery code.",
  "server.secrets.recoveryLabel": "Recovery code",
  "server.secrets.recover": "Unlock",
  "server.secrets.error": "Could not do that: {error}",
  "server.secrets.unpaired": "This browser holds no paired device key. Set the key up from the phone app, or from a browser you paired at the server's address.",
  "server.secrets.noRecoveryCode": "Unlocked, but no recovery code opens the current key (it was made by an older version). Make a new recovery code now.",
  "server.secrets.repin.header": "This server's identity key changed",
  "server.secrets.repin.help": "This device no longer recognises the server's identity key (it was lost or restored from a backup — or something between you and the server answers), so it releases nothing to it. If you expected this, enter your recovery code: this device checks the new key against it before trusting it. The code is not sent to the server.",
  "server.secrets.repin.submit": "Trust the new key",
  "server.secrets.repin.later": "Later",
  "server.secrets.repin.close": "Close",
  "server.secrets.repin.done": "The new key is trusted. Mail and saved passwords unlock again.",
  "server.secrets.repin.mismatch": "That recovery code does not confirm this key. Check the code; if it is right, this key does not come from your server — do not trust it.",
  "server.secrets.repin.outdated": "This server's recovery wrap is from an older version. Unlock once with the recovery code in Settings → Mobile → Server, then try again.",
  "server.secrets.newCodeHeader": "New recovery code recommended",
  "server.secrets.newCodeAdvice": "A device was disconnected after your recovery code was made. Make a new code: until you do, someone holding that device and an old copy of this server's files could fake a “server key changed” prompt that your old code would confirm.",
  "server.secrets.newCodeAdviceLocked": "A device was disconnected after your recovery code was made. Once the key is unlocked (sign in on a paired device), make a new recovery code here.",
  "server.secrets.newCodeNow": "Make a new recovery code",
  "server.secrets.newCodeLater": "Later",
  "server.secrets.mailRekey.running": "Re-encrypting your mail under a new key after the disconnect: {percent} %. Mail stays usable meanwhile.",
  "server.secrets.mailRekey.waiting": "Re-encrypting your mail under a new key after the disconnect: waiting until a paired device unlocks the key.",
  "server.secrets.mailRekey.waitingOpen": "Re-encrypting your mail under a new key after the disconnect: starts the next time mail is opened on this server.",
  "server.secrets.mailRekey.failed": "Re-encrypting your mail under a new key stopped: {error}. It is retried at the next unlock.",
  "server.settings.error": "The server refused: {error}",
  "server.agentKeys.header": "Agent credentials (administrator)",
  "server.agentKeys.help": "Offer an API key per agent CLI and choose which users of this server may use it — nobody until you add them. Each of them decides in Manage CLIs whether their agents use it or their own login. Delivered directly, every agent of a user who picks it can read the key, and there is no per-user budget; through the key broker (Claude) each user gets a token of their own and a monthly budget instead. A saved key is never shown again. Withdrawing it, or taking a user off its list, stops their new agents at once and their running Claude agents within minutes; other agents already running keep it — revoke the key at the provider to take it from them.",
  "server.agentKeys.unreachable": "The key keeper does not answer. Check {slug}-auth-keeper.socket on the server.",
