  "pill.vmEgressProxyCaveat": "The VM reaches only the hosts below through {app}'s proxy; everything else is blocked and logged. Honest limit: an agent can still send data to the allowed endpoints (e.g. inside a model prompt) — the proxy narrows the channel, it cannot close it. Egress-mode changes apply at the next boot.",
