  "pill.vmMailReader": "Mail reader",
  "pill.vmMailReaderHelp": "Agent tabs in this VM may read the mail accounts you opened to agents, and write drafts. Its way out is narrowed and logged, not sealed: the agent still reaches its own provider, which receives what it reads. It can never send — only a draft you send yourself leaves. Applies from the next boot; no mirror, and files you download from this VM may carry mail content.",
