  "pill.pythonInterpreterEllipsis": "Python interpreter…",
  "pill.autoConnectTitleNonHeadless": "Connect this project by itself on launch and when you switch to it. {app} handles no passwords in this mode, so the login (and the VPN, if it has one) opens in the root terminal for you to authenticate — then the project connects on its own.",
