  "pill.autoConnectOnLaunch": "Auto-connect on launch",
  "pill.persistSessionsMenuTitle": "Run this project's remote shell, Python/script AND agent tabs (Claude, Codex, …) inside a tmux session on the host, so a long run — or a live agent — keeps going through an SSH drop, a laptop sleep, or {app} quitting, and the tab reattaches when you reconnect. An agent reattaches its running process; if the host session is gone it resumes the conversation instead. Closing a tab detaches it (the session lives on, reattachable from the Sessions view).",
