  "remoteConnect.autoConnectVpnWarningPre": "Heads up: if the host isn't reachable directly, auto-connect brings the VPN up",
  "remoteConnect.autoConnectVpnWarningStrong": "without asking",
  "remoteConnect.autoConnectVpnWarningPost": "— rerouting this computer's traffic on launch. The header's VPN indicator shows when a tunnel is up, and can bring it down.",
  "remoteConnect.autoConnectInteractiveTitle": "Connect this project by itself on launch and when you switch to it. {app} handles no passwords in this mode, so the login (and the VPN, if this project has one) opens in the root terminal for you to authenticate — the project connects on its own once you're in.",
  "remoteConnect.autoConnectInteractiveHint": "on launch and on switch — opens the login in the root terminal",
