  "remoteConnect.forgetPasswordBtn": "Forget saved password",
  "carefulHost.title": "Keep {app}'s background work off this machine: the file-size census stops scanning the host by itself, and monitoring gets cheaper and slower. Use it for a login node or any machine you share with others — not for a compute node you hold for the length of a job, which is yours while you have it.",
  "carefulHost.label": "Go easy on this machine",
  "carefulHost.hintDefault": "for a login node or a shared box: skip the scans that read its whole filesystem",
  "carefulHost.hintOnByDefault": "on by default for every remote machine — flip it off if this one is yours",
  "carefulHost.hintNotCareful": "this machine is yours: full monitoring, same as local",
  "carefulHost.hintHpcTagged": "always on: this machine is tagged as an HPC cluster login node",
  "hpcHost.title": "Tag this machine as a shared cluster login node. {app} then never scans or measures its filesystem by itself, runs no background file or Git sync against it, never connects to it silently at launch, reads it lightly whatever the reading switch says, and asks before a run lands on it. Nothing detects this — a scheduler on PATH says the machine has SLURM, not that its operators mind.",
  "hpcHost.label": "HPC cluster (login node)",
  "hpcHost.hintOn": "background work off, light reading forced, runs ask first",
  "hpcHost.hintOff": "tick it for a cluster login node — never for a compute node you hold through a job",
