  "gitPushMcp.title": "Let project agents ask {app} to push, tag releases and read CI (MCP)",
  "gitPushMcp.help": "On by default. Local Claude, Codex and Vibe (MCP) tabs can push the current branch or tag a release with your stored token — fast-forward only, never force or the default branch. Per project: Off, Propose (default, asks you) or Apply; releases always ask. Agents can also read CI runs and code-scanning alerts, only for the repo confirmed for pushes or one you allow on an \"Allow CI\" card. Local tabs only.",
