  "caldav.intro": "A CalDAV account syncs calendars from a server you log in to. For a read-only link somebody shared with you, use Subscribe instead.",
  "caldav.accountName": "Name",
  "caldav.serverUrl": "Server URL",
  "caldav.serverUrlHint": "The address of the server, or of the calendar itself if your provider gives you one. Your provider's CalDAV documentation names it.",
  "caldav.httpRefused": "This server address is not encrypted (http://), so {app} will not use it: your password and your calendar would cross the network in the clear. Use an https:// address — for a server on your own machine (Radicale, for example) put a TLS proxy in front of it. An account already set up with http:// keeps its calendars here but no longer syncs.",
  "caldav.user": "Username",
  "caldav.password": "Password",
  "caldav.passwordHint": "Some servers want an app-specific password rather than your normal one — check your provider's account settings if signing in fails.",
