  "caldav.syncInterval": "Check every (minutes)",
  "caldav.syncIntervalHint": "0 means never — only when you click Sync.",
  "caldav.allowWrite": "Send my changes to this server",
  "caldav.requireVpn": "Only connect while the VPN is up",
  "caldav.requireVpnHint": "For a calendar server that is only reachable from inside its network. While no OpenVPN tunnel is up, this account is skipped instead of failing, and it is synced as soon as one comes up. Only tunnels started from {app} count.",
  "caldav.allowWriteHint": "Off by default. While it is off, this account's calendars are read-only here — nothing you change is sent, and nothing is silently held back. Turning it on lets edits, new entries and deletions reach the server. A calendar the server marks read-only for your login stays read-only either way.",
