  "hpcGuard.duScan.title": "Scan the whole tree on a cluster?",
  "hpcGuard.duScan.body": "This walks every file under the project root to add up sizes. On a cluster that root normally lives on the parallel filesystem, where a recursive walk means one metadata request per file against a server the whole site shares — the read filesystem guides ask you not to do casually. It is one scan, not a loop, so it is yours to run if you want it.",
  "hpcGuard.duScan.go": "Scan anyway",
  "hpcGuard.census.title": "Measure the host's folders on a cluster?",
  "hpcGuard.census.body": "The giant-folder census runs `du` over the whole host tree to find what is too big to sync. Same metadata cost as a full scan, and this one normally runs by itself on connect — which is why it stays off here unless you ask.",
  "hpcGuard.census.go": "Measure anyway",
  "hpcGuard.connect.title": "Log in to this cluster?",
  "hpcGuard.connect.body": "Opening this tab would dial the machine and leave a shared SSH master standing on it (and, for a persistent tab, a tmux server with it) — the unattended presence the tag exists to prevent. That is right for a tab restored at relaunch, which nobody asked for; it is only in the way when you meant to open one. Going ahead connects the project first, then opens the tab.",
  "hpcGuard.connect.go": "Connect and open",
  "hpcGuard.loginNodeRun.title": "Run this on the login node?",
  "hpcGuard.loginNodeRun.body": "This would run on the cluster's login node, which is shared with everyone logged in right now. Sites ask you to keep CPU-intensive work off it and reserve the right to kill processes that load it for long. The compliant route for the same work is an interactive job — the Jobs view's srun shell — or a batch script with sbatch.",
  "hpcGuard.loginNodeRun.go": "Run here anyway",
  "hpcGuard.note": "You tagged this machine as a cluster login node. Untag it in the Machines menu if that was wrong — nothing here is remembered, so this asks again next time.",
  "unfencedPlatform.title": "Agents on this computer run with your full rights",
  "unfencedPlatform.body": "Windows has no agent sandbox. An agent started here can read and change everything your account can: other projects, saved passwords, SSH keys, your browser profile. On Linux and macOS {app} keeps agents sandboxed to their project; here it cannot.",
  "unfencedPlatform.alternative": "Accept to start agents on this computer from now on — {app} asks once. Prefer a boundary? Open the project in a container instead.",
  "unfencedPlatform.accept": "Accept and start",
  "unfencedPlatform.declined": "Not started: agents on this computer run with your full rights, and that was not accepted. Open a new agent tab to be asked again, or open the project in a container.",
  "apiProxyPort.title": "The API proxy's port was taken",
  "apiProxyPort.lede": "After a crash, {app}'s API proxy binds the port it used before, so agents that survived keep reaching it. Port {port} was held by {holder}, so the proxy now runs on port {newPort}.",
